// TestSniffImage covers the magic table: the three stored formats, plus the
// refusals (too-short prefixes, GIF, empty).
func TestSniffImage(t *testing.T) {
	webpHeader := append([]byte("RIFF"), 0x24, 0x00, 0x00, 0x00)
	webpHeader = append(webpHeader, []byte("WEBP")...)
	cases := []struct {
		name string
		b    []byte
		want string
	}{
		{"jpeg", []byte{0xFF, 0xD8, 0xFF, 0xE0, 0x00, 0x10}, "jpeg"},
		{"png", append([]byte{0x89, 'P', 'N', 'G', 0x0D, 0x0A, 0x1A, 0x0A}, 0x0D), "png"},
		{"webp", webpHeader, "webp"},
		{"too_short", []byte{0xFF, 0xD8}, ""},
		{"gif_rejected", []byte("GIF89a\x01\x00\x01\x00"), ""},
		{"empty", nil, ""},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			if got := sniffImage(tc.b); got != tc.want {
				t.Fatalf("sniffImage = %q, want %q", got, tc.want)
			}
		})
	}
}

// TestGuard covers the shared image gate at the unit level: real JPEG bytes
// pass (ext reported), while the oversized, unknown-magic, and
// corrupt-but-sniffing cases are refused with the sentinels.
func TestGuard(t *testing.T) {
	t.Run("accepts_real_jpeg", func(t *testing.T) {
		ext, err := guard(jpegBytes(t, 8, 8))
		if err != nil {
			t.Fatalf("guard(real jpeg) = %v", err)
		}
		if ext != "jpeg" {
			t.Fatalf("ext = %q, want jpeg", ext)
		}
	})
	t.Run("too_large", func(t *testing.T) {
		oversize := bytes.Repeat([]byte{0xFF, 0xD8, 0xFF}, 3<<20)
		if _, err := guard(oversize); !errors.Is(err, ErrTooLarge) {
			t.Fatalf("guard(9 MiB) = %v, want errors.Is ErrTooLarge", err)
		}
	})
	t.Run("not_image", func(t *testing.T) {
		if _, err := guard([]byte("plain text")); !errors.Is(err, ErrNotImage) {
			t.Fatalf("guard(text) = %v, want errors.Is ErrNotImage", err)
		}
	})
	t.Run("corrupt_sniffing_jpeg", func(t *testing.T) {
		corrupt := append([]byte{0xFF, 0xD8, 0xFF, 0xE0}, bytes.Repeat([]byte{0x00}, 1024)...)
		if _, err := guard(corrupt); !errors.Is(err, ErrNotImage) {
			t.Fatalf("guard(corrupt) = %v, want errors.Is ErrNotImage", err)
		}
	})
}
